-- GenDB engine variant Q02-wrapped_tables: template q02.sql, kind wrapped_tables (generated by generate.py; frozen)
SELECT
  s_acctbal,
  s_name,
  n_name,
  p_partkey,
  p_mfgr,
  s_address,
  s_phone,
  s_comment
FROM (
  SELECT
    *
  FROM part
) AS part, (
  SELECT
    *
  FROM supplier
) AS supplier, (
  SELECT
    *
  FROM partsupp
) AS partsupp, (
  SELECT
    *
  FROM nation
) AS nation, (
  SELECT
    *
  FROM region
) AS region
WHERE
  p_partkey = ps_partkey
  AND s_suppkey = ps_suppkey
  AND p_size = $1
  AND p_type LIKE $2
  AND s_nationkey = n_nationkey
  AND n_regionkey = r_regionkey
  AND r_name = $3
  AND ps_supplycost = (
    SELECT
      MIN(ps_supplycost)
    FROM (
      SELECT
        *
      FROM partsupp
    ) AS partsupp, (
      SELECT
        *
      FROM supplier
    ) AS supplier, (
      SELECT
        *
      FROM nation
    ) AS nation, (
      SELECT
        *
      FROM region
    ) AS region
    WHERE
      p_partkey = ps_partkey
      AND s_suppkey = ps_suppkey
      AND s_nationkey = n_nationkey
      AND n_regionkey = r_regionkey
      AND r_name = $3
  )
ORDER BY
  s_acctbal DESC,
  n_name,
  s_name,
  p_partkey
LIMIT 100
